    else { $description = $title . '-ஐ ஒரு கையால் அமைக்கவும். சரியான திசை மற்றும் விரல் நிலையை MFD BIM சைகை வங்கியில் சரிபார்க்கவும்.'; $tip = 'நுண்ணிய கை வடிவத்தை ஒப்பிடவும்'; }
